def window(months):
    if not isinstance(months,int) or isinstance(months,bool) or not 0<=months<MAX_MONTHS:return None
    lo=months if months<24 else months//2*2
    return lo,min(lo+(1 if months<24 else 2),MAX_MONTHS)

def entry(months):
    bounds=window(months)
    if not bounds:return None
    lo,hi=bounds
    row=EARLY[lo] if lo<24 else LATER[(lo-24)//2]
    return lo,hi,row

def play_support(months):
    lo,_=window(months)
    return PLAY_SUPPORT[lo] if lo<24 else LATER_SUPPORT[(lo-24)//2]

def advice(months):
    value=entry(months)
    if not value:return []
    lo,hi,(title,body,care_title,care_body)=value
    stamp=str(lo)
    care_source=BABY if months<12 else CARE
    return [
      dict(id='month-development-'+stamp,category='Развитие',section='Развитие',title=title,text=body,source=CDC,sourceTitle='Возрастные ориентиры: редакционная адаптация',priority=2,minMonths=lo,maxMonths=hi),
      dict(id='month-care-'+stamp,category='Уход и гигиена',section='Уход и гигиена',title=care_title,text=care_body,source=care_source,sourceTitle='Рекомендации по уходу: редакционная адаптация',priority=2,minMonths=lo,maxMonths=hi),
      dict(id='month-observation-'+stamp,category='Советы педиатров',section='Советы педиатров',title='Наблюдение за общением и самочувствием',text='В выбранном занятии «'+title+'» замечайте, как ребёнок выражает интерес и принимает помощь. Отказ или трудность в одной игре не определяют развитие. Если исчез уже освоенный навык, появилась боль или вас тревожат повторяющиеся трудности, обсудите конкретные наблюдения с педиатром.',source=CDC,sourceTitle='Наблюдение за развитием',priority=2,minMonths=lo,maxMonths=hi),
    ]

assert len(EARLY)==len(PLAY_SUPPORT)==24
assert len(LATER)==len(LATER_SUPPORT)==31
